class Supplier extends DataClass implements Insertable<Supplier> {
  final int id;
  final String name;

  /// Optional, normalized A-Z / 0-9 prefix, unique across ALL suppliers,
  /// including inactive ones. Schema guards prevent reassigning issued codes.
  final String? productCode;
  final String? email;
  final String? phone;
  final String? address;

  /// UI default only. Every consignment receipt must still reference an active
  /// agreement; this field never changes accounting by itself.
  final String defaultSupplyMode;
  final Decimal balanceCents;

  /// The initial balance when the supplier was created (immutable after creation)
  final Decimal openingBalanceCents;
  final int currencyId;
  final bool isActive;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Supplier({
    required this.id,
    required this.name,
    this.productCode,
    this.email,
    this.phone,
    this.address,
    required this.defaultSupplyMode,
    required this.balanceCents,
    required this.openingBalanceCents,
    required this.currencyId,
    required this.isActive,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || productCode != null) {
      map['product_code'] = Variable<String>(productCode);
    }
    if (!nullToAbsent || email != null) {
      map['email'] = Variable<String>(email);
    }
    if (!nullToAbsent || phone != null) {
      map['phone'] = Variable<String>(phone);
    }
    if (!nullToAbsent || address != null) {
      map['address'] = Variable<String>(address);
    }
    map['default_supply_mode'] = Variable<String>(defaultSupplyMode);
    {
      map['balance_cents'] = Variable<int>(
        $SuppliersTable.$converterbalanceCents.toSql(balanceCents),
      );
    }
    {
      map['opening_balance_cents'] = Variable<int>(
        $SuppliersTable.$converteropeningBalanceCents.toSql(
          openingBalanceCents,
        ),
      );
    }
    map['currency_id'] = Variable<int>(currencyId);
    map['is_active'] = Variable<bool>(isActive);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  SuppliersCompanion toCompanion(bool nullToAbsent) {
    return SuppliersCompanion(
      id: Value(id),
      name: Value(name),
      productCode: productCode == null && nullToAbsent
          ? const Value.absent()
          : Value(productCode),
      email: email == null && nullToAbsent
          ? const Value.absent()
          : Value(email),
      phone: phone == null && nullToAbsent
          ? const Value.absent()
          : Value(phone),
      address: address == null && nullToAbsent
          ? const Value.absent()
          : Value(address),
      defaultSupplyMode: Value(defaultSupplyMode),
      balanceCents: Value(balanceCents),
      openingBalanceCents: Value(openingBalanceCents),
      currencyId: Value(currencyId),
      isActive: Value(isActive),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Supplier.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Supplier(
      id: serializer.fromJson<int>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      productCode: serializer.fromJson<String?>(json['productCode']),
      email: serializer.fromJson<String?>(json['email']),
      phone: serializer.fromJson<String?>(json['phone']),
      address: serializer.fromJson<String?>(json['address']),
      defaultSupplyMode: serializer.fromJson<String>(json['defaultSupplyMode']),
      balanceCents: serializer.fromJson<Decimal>(json['balanceCents']),
      openingBalanceCents: serializer.fromJson<Decimal>(
        json['openingBalanceCents'],
      ),
      currencyId: serializer.fromJson<int>(json['currencyId']),
      isActive: serializer.fromJson<bool>(json['isActive']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'name': serializer.toJson<String>(name),
      'productCode': serializer.toJson<String?>(productCode),
      'email': serializer.toJson<String?>(email),
      'phone': serializer.toJson<String?>(phone),
      'address': serializer.toJson<String?>(address),
      'defaultSupplyMode': serializer.toJson<String>(defaultSupplyMode),
      'balanceCents': serializer.toJson<Decimal>(balanceCents),
      'openingBalanceCents': serializer.toJson<Decimal>(openingBalanceCents),
      'currencyId': serializer.toJson<int>(currencyId),
      'isActive': serializer.toJson<bool>(isActive),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

  Supplier copyWith({
    int? id,
    String? name,
    Value<String?> productCode = const Value.absent(),
    Value<String?> email = const Value.absent(),
    Value<String?> phone = const Value.absent(),
    Value<String?> address = const Value.absent(),
    String? defaultSupplyMode,
    Decimal? balanceCents,
    Decimal? openingBalanceCents,
    int? currencyId,
    bool? isActive,
    DateTime? createdAt,
    DateTime? updatedAt,
  }) => Supplier(
    id: id ?? this.id,
    name: name ?? this.name,
    productCode: productCode.present ? productCode.value : this.productCode,
    email: email.present ? email.value : this.email,
    phone: phone.present ? phone.value : this.phone,
    address: address.present ? address.value : this.address,
    defaultSupplyMode: defaultSupplyMode ?? this.defaultSupplyMode,
    balanceCents: balanceCents ?? this.balanceCents,
    openingBalanceCents: openingBalanceCents ?? this.openingBalanceCents,
    currencyId: currencyId ?? this.currencyId,
    isActive: isActive ?? this.isActive,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
  );
  Supplier copyWithCompanion(SuppliersCompanion data) {
    return Supplier(
      id: data.id.present ? data.id.value : this.id,
      name: data.name.present ? data.name.value : this.name,
      productCode: data.productCode.present
          ? data.productCode.value
          : this.productCode,
      email: data.email.present ? data.email.value : this.email,
      phone: data.phone.present ? data.phone.value : this.phone,
      address: data.address.present ? data.address.value : this.address,
      defaultSupplyMode: data.defaultSupplyMode.present
          ? data.defaultSupplyMode.value
          : this.defaultSupplyMode,
      balanceCents: data.balanceCents.present
          ? data.balanceCents.value
          : this.balanceCents,
      openingBalanceCents: data.openingBalanceCents.present
          ? data.openingBalanceCents.value
          : this.openingBalanceCents,
      currencyId: data.currencyId.present
          ? data.currencyId.value
          : this.currencyId,
      isActive: data.isActive.present ? data.isActive.value : this.isActive,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Supplier(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('productCode: $productCode, ')
          ..write('email: $email, ')
          ..write('phone: $phone, ')
          ..write('address: $address, ')
          ..write('defaultSupplyMode: $defaultSupplyMode, ')
          ..write('balanceCents: $balanceCents, ')
          ..write('openingBalanceCents: $openingBalanceCents, ')
          ..write('currencyId: $currencyId, ')
          ..write('isActive: $isActive, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    name,
    productCode,
    email,
    phone,
    address,
    defaultSupplyMode,
    balanceCents,
    openingBalanceCents,
    currencyId,
    isActive,
    createdAt,
    updatedAt,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Supplier &&
          other.id == this.id &&
          other.name == this.name &&
          other.productCode == this.productCode &&
          other.email == this.email &&
          other.phone == this.phone &&
          other.address == this.address &&
          other.defaultSupplyMode == this.defaultSupplyMode &&
          other.balanceCents == this.balanceCents &&
          other.openingBalanceCents == this.openingBalanceCents &&
          other.currencyId == this.currencyId &&
          other.isActive == this.isActive &&
          other.createdAt == this.createdAt &&
          other.updatedAt == this.updatedAt);
}

