class Purchase extends DataClass implements Insertable<Purchase> {
  /// Frozen internal route. NULL preserves the existing primary warehouse.
  final String? warehouseId;
  final int id;
  final String purchaseNumber;
  final int supplierId;
  final Decimal subtotalCents;
  final Decimal discountCents;
  final Decimal taxCents;
  final Decimal totalCents;
  final Decimal paidAmountCents;
  final int currencyId;
  final String status;
  final String? paymentMethod;
  final String? supplierInvoiceRef;
  final String? notes;
  final DateTime purchaseDate;
  final DateTime? dueDate;

  /// Phase 11.2 — pricing engine version snapshot. See `Sales` for docs.
  final String? pricingEngineVersion;

