class PurchaseItem extends DataClass implements Insertable<PurchaseItem> {
  final int id;
  final int purchaseId;
  final int productId;
  final int? variantId;
  final int quantity;
  final int quantityScale;
  final String measurementType;
  final Decimal unitCostCents;

  /// Exact rounded-pool value added to inventory when this purchase posted.
  final Decimal? inventoryValueAtPostCents;
  final Decimal discountCents;
  final Decimal subtotalCents;
  final Decimal taxCents;
  final Decimal totalCents;
  final Decimal? originalCostCents;
  final Decimal? originalPriceCents;
  final Decimal? originalWholesalePriceCents;
  final Decimal? newSellPriceCents;
  final Decimal? newWholesalePriceCents;

  /// Manufacturer-assigned batch/lot identifier (GS1 AI 10). Unlike the
  /// app's internal batch number this value is not globally unique: the same
  /// lot may arrive across multiple purchase documents.
  final String? manufacturerLotNumber;
  final DateTime? expiryDate;

  /// Atomic returned-quantity counter (linked path).
  /// Bumped inside `postPurchaseReturn`, decremented inside `voidPurchaseReturn`.
  /// Phase 0 server-side cap to stop over-returning across multiple invoices.
  final int qtyReturnedLinked;

  /// Atomic returned-quantity counter (adjustment / unlinked path).
  /// Bumped inside `postPurchaseAdjReturn`, decremented inside `voidPurchaseAdjReturn`.
  /// Combined with `qtyReturnedLinked` to form the total returned units.
  final int qtyReturnedAdjustment;
  final DateTime createdAt;

  /// Opt-in captured when this purchase line is saved. Not inferred later
  /// from a supplier's current prefix or from a global settings change.
  final bool supplierIdentityRequested;
  final int? supplierIdentityId;
