          ..write('newSellPriceCents: $newSellPriceCents, ')
          ..write('newWholesalePriceCents: $newWholesalePriceCents, ')
          ..write('manufacturerLotNumber: $manufacturerLotNumber, ')
          ..write('expiryDate: $expiryDate, ')
          ..write('qtyReturnedLinked: $qtyReturnedLinked, ')
          ..write('qtyReturnedAdjustment: $qtyReturnedAdjustment, ')
          ..write('createdAt: $createdAt, ')
          ..write('supplierIdentityRequested: $supplierIdentityRequested, ')
          ..write('supplierIdentityId: $supplierIdentityId')
          ..write(')'))
        .toString();
  }
}

