class ProductBatch extends DataClass implements Insertable<ProductBatch> {
  /// Creation route only; immutable document location remains the history source.
  /// NULL preserves the default route for legacy inserts.
  final String? warehouseId;
  final int id;
  final int productId;
  final int? variantId;

  /// Human-readable unique batch identifier, e.g. `BATCH-202604-12-3`.
  final String batchNumber;

  /// Manufacturer-assigned batch/lot identifier printed on the pack
  /// (GS1 Application Identifier 10). It is deliberately non-unique because
  /// one manufacturer lot can be received in more than one purchase.
  final String? manufacturerLotNumber;

  /// Source purchase item that created this batch (null for opening / found /
  /// return-originated batches). Restrict prevents losing audit trail.
  final int? purchaseItemId;
  final int? supplierId;

  /// Filled on a batch recreated at the destination of a warehouse transfer.
  /// The immediate link preserves the complete lot chain across many moves.
  final int? originBatchId;

  /// Polymorphic link validated by transfer SQL guards. Kept as text here to
  /// avoid a circular table import between products and warehouse transfers.
  final String? transferAllocationId;

  /// One of: 'purchase' | 'opening' | 'found' | 'sale_return' |
  ///         'warehouse_transfer'.
  final String source;
  final DateTime receivedDate;
  final DateTime? expiryDate;

  /// Quantity received at creation. Immutable.
  final int receivedQuantity;

  /// Currently available quantity. Mutated only by [BatchConsumptions] postings.
  final int remainingQuantity;

  /// Unit cost in cents — FROZEN at creation (revaluation adjustments aside).
  final Decimal unitCostCents;
  final bool isActive;
  final DateTime createdAt;
  final DateTime updatedAt;
  const ProductBatch({
    this.warehouseId,
    required this.id,
    required this.productId,
    this.variantId,
    required this.batchNumber,
    this.manufacturerLotNumber,
    this.purchaseItemId,
    this.supplierId,
    this.originBatchId,
    this.transferAllocationId,
    required this.source,
    required this.receivedDate,
    this.expiryDate,
    required this.receivedQuantity,
    required this.remainingQuantity,
    required this.unitCostCents,
    required this.isActive,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (!nullToAbsent || warehouseId != null) {
      map['warehouse_id'] = Variable<String>(warehouseId);
    }
    map['id'] = Variable<int>(id);
    map['product_id'] = Variable<int>(productId);
    if (!nullToAbsent || variantId != null) {
      map['variant_id'] = Variable<int>(variantId);
    }
    map['batch_number'] = Variable<String>(batchNumber);
    if (!nullToAbsent || manufacturerLotNumber != null) {
      map['manufacturer_lot_number'] = Variable<String>(manufacturerLotNumber);
    }
    if (!nullToAbsent || purchaseItemId != null) {
      map['purchase_item_id'] = Variable<int>(purchaseItemId);
    }
    if (!nullToAbsent || supplierId != null) {
      map['supplier_id'] = Variable<int>(supplierId);
    }
    if (!nullToAbsent || originBatchId != null) {
      map['origin_batch_id'] = Variable<int>(originBatchId);
    }
    if (!nullToAbsent || transferAllocationId != null) {
      map['transfer_allocation_id'] = Variable<String>(transferAllocationId);
    }
    map['source'] = Variable<String>(source);
    map['received_date'] = Variable<DateTime>(receivedDate);
    if (!nullToAbsent || expiryDate != null) {
      map['expiry_date'] = Variable<DateTime>(expiryDate);
    }
    map['received_quantity'] = Variable<int>(receivedQuantity);
    map['remaining_quantity'] = Variable<int>(remainingQuantity);
    {
      map['unit_cost_cents'] = Variable<int>(
        $ProductBatchesTable.$converterunitCostCents.toSql(unitCostCents),
      );
    }
    map['is_active'] = Variable<bool>(isActive);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

