  String toString() {
    return (StringBuffer('Customer(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('email: $email, ')
          ..write('phone: $phone, ')
          ..write('address: $address, ')
          ..write('balanceCents: $balanceCents, ')
          ..write('openingBalanceCents: $openingBalanceCents, ')
