class Sale extends DataClass implements Insertable<Sale> {
  final String? warehouseId;
  final int id;
  final String invoiceNumber;
  final int? customerId;
  final int? employeeId;
  final int? cashierShiftId;
  final Decimal subtotalCents;
  final Decimal taxCents;
  final Decimal discountCents;
  final Decimal totalCents;
  final Decimal paidAmountCents;
  final int currencyId;
  final String paymentMethod;
  final String status;
  final String? notes;

  /// Client-generated token used by LAN/offline retries. A repeated request
  /// returns the original sale instead of posting stock and journals twice.
  final String? idempotencyKey;
  final DateTime saleDate;
  final DateTime? dueDate;

  /// Phase 11.2 — pricing engine version that produced this row's
  /// `subtotal/discount/tax/total`. NULL for legacy rows. See
  /// `PricingEngineVersion`.
  final String? pricingEngineVersion;

  /// Phase 11.2 — tax-inclusive setting in force at post time. NULL for
  /// legacy rows. Used by audit / replay to reproduce the breakdown.
  final bool? taxInclusiveAtPost;

  /// Phase 11.2 — rounding mode in force at post time (`halfUp` |
  /// `halfEven` | `down`). NULL for legacy rows.
  final String? roundingModeAtPost;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Sale({
    this.warehouseId,
    required this.id,
    required this.invoiceNumber,
    this.customerId,
    this.employeeId,
    this.cashierShiftId,
    required this.subtotalCents,
    required this.taxCents,
    required this.discountCents,
    required this.totalCents,
    required this.paidAmountCents,
    required this.currencyId,
    required this.paymentMethod,
    required this.status,
    this.notes,
    this.idempotencyKey,
    required this.saleDate,
    this.dueDate,
    this.pricingEngineVersion,
    this.taxInclusiveAtPost,
    this.roundingModeAtPost,
    required this.createdAt,
    required this.updatedAt,
