class SaleItem extends DataClass implements Insertable<SaleItem> {
  final int id;
  final int saleId;
  final int productId;
  final int? variantId;

  /// Exact supplier/product identity selected by scanning or explicit source
  /// selection. Null keeps the normal allocation policy and never implies the
  /// product card's preferred supplier.
  final int? supplierIdentityId;

  /// Exact supplier-owned custody layer chosen by the operator. Null keeps the
  /// normal issue policy. It is mutually exclusive with [supplierIdentityId].
  final String? consignmentLayerId;
  final int? employeeId;
  final int quantity;
  final int quantityScale;
  final String measurementType;
  final Decimal unitPriceCents;
  final Decimal subtotalCents;
  final Decimal discountCents;

  /// Immutable split of the displayed line discount for new postings.
  /// Legacy rows stay NULL because their two components cannot be proven.
  final Decimal? itemDiscountAtPostCents;
  final Decimal? invoiceDiscountAtPostCents;
  final Decimal taxCents;
  final Decimal totalCents;

  /// Frozen cost-per-unit at the time the sale was posted.
  /// NULL for legacy rows created before this column existed.
  final Decimal? costCents;

  /// Exact rounded-pool value removed from inventory when this sale posted.
  final Decimal? inventoryValueAtPostCents;

  /// Atomic returned-quantity counter (linked path).
  /// Bumped inside `postSaleReturn`, decremented inside `voidSaleReturn`.
  /// Used as the authoritative server-side cap so an over-return cannot slip
  /// through any UI / reporting drift (Phase 0 hard guard).
  final int qtyReturnedLinked;

  /// Atomic returned-quantity counter (adjustment / unlinked path).
  /// Bumped inside `postSaleAdjReturn`, decremented inside `voidSaleAdjReturn`.
  /// Combined with `qtyReturnedLinked` to form the total returned units
  /// against the original `quantity`, regardless of which return flow a
  /// user picked (linked vs adjustment).
  final int qtyReturnedAdjustment;
  final DateTime createdAt;
  const SaleItem({
    required this.id,
    required this.saleId,
    required this.productId,
    this.variantId,
    this.supplierIdentityId,
    this.consignmentLayerId,
    this.employeeId,
    required this.quantity,
    required this.quantityScale,
    required this.measurementType,
    required this.unitPriceCents,
    required this.subtotalCents,
    required this.discountCents,
    this.itemDiscountAtPostCents,
    this.invoiceDiscountAtPostCents,
    required this.taxCents,
    required this.totalCents,
    this.costCents,
    this.inventoryValueAtPostCents,
    required this.qtyReturnedLinked,
    required this.qtyReturnedAdjustment,
    required this.createdAt,
  });
