class InventoryAdjustment extends DataClass
    implements Insertable<InventoryAdjustment> {
  /// Optional creation route; the immutable document location owns history.
  final String? warehouseId;
  final int id;
  final String adjustmentNumber;
  final int productId;
  final int? variantId;

  /// 'shrinkage' | 'gain' | 'revaluation'
  final String adjustmentType;

  /// Signed change in on-hand quantity (0 for pure revaluations).
  final int quantityDelta;

  /// Unit cost used to value this adjustment. For revaluations this is the
  /// NEW unit cost. For shrinkage/gain this is the cost at time of event.
  final Decimal unitCostCents;

  /// |quantityDelta| × unitCostCents for shrinkage/gain; for revaluation it
  /// equals (newCost − oldCost) × onHandQty (sign preserved).
  final Decimal totalValueCents;

  /// Previous unit cost — only meaningful for revaluations (nullable).
  final Decimal? previousUnitCostCents;

  /// Mandatory human-readable reason. Enforced non-empty by the service.
  final String reason;
  final String? notes;
  final int currencyId;
  final int? userId;

  /// FK to the posted journal entry. Never null after post; nullable only to
  /// survive a partial insert that gets rolled back.
  final int? journalEntryId;

  /// Costing method active when this adjustment was recorded. Enables a
  /// future FIFO migration without losing historical WAC semantics.
  final String costingMethod;
  final DateTime createdAt;
  final DateTime updatedAt;
  const InventoryAdjustment({
    this.warehouseId,
    required this.id,
    required this.adjustmentNumber,
    required this.productId,
    this.variantId,
    required this.adjustmentType,
    required this.quantityDelta,
    required this.unitCostCents,
    required this.totalValueCents,
    this.previousUnitCostCents,
    required this.reason,
    this.notes,
    required this.currencyId,
    this.userId,
    this.journalEntryId,
    required this.costingMethod,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (!nullToAbsent || warehouseId != null) {
      map['warehouse_id'] = Variable<String>(warehouseId);
    }
    map['id'] = Variable<int>(id);
    map['adjustment_number'] = Variable<String>(adjustmentNumber);
    map['product_id'] = Variable<int>(productId);
    if (!nullToAbsent || variantId != null) {
      map['variant_id'] = Variable<int>(variantId);
    }
    map['adjustment_type'] = Variable<String>(adjustmentType);
    map['quantity_delta'] = Variable<int>(quantityDelta);
    {
      map['unit_cost_cents'] = Variable<int>(
        $InventoryAdjustmentsTable.$converterunitCostCents.toSql(unitCostCents),
      );
    }
    {
      map['total_value_cents'] = Variable<int>(
        $InventoryAdjustmentsTable.$convertertotalValueCents.toSql(
          totalValueCents,
        ),
      );
    }
    if (!nullToAbsent || previousUnitCostCents != null) {
      map['previous_unit_cost_cents'] = Variable<int>(
        $InventoryAdjustmentsTable.$converterpreviousUnitCostCentsn.toSql(
          previousUnitCostCents,
        ),
      );
    }
    map['reason'] = Variable<String>(reason);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['currency_id'] = Variable<int>(currencyId);
    if (!nullToAbsent || userId != null) {
      map['user_id'] = Variable<int>(userId);
    }
    if (!nullToAbsent || journalEntryId != null) {
      map['journal_entry_id'] = Variable<int>(journalEntryId);
    }
    map['costing_method'] = Variable<String>(costingMethod);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  InventoryAdjustmentsCompanion toCompanion(bool nullToAbsent) {
    return InventoryAdjustmentsCompanion(
      warehouseId: warehouseId == null && nullToAbsent
          ? const Value.absent()
          : Value(warehouseId),
