class PurchaseReturnAdjustment extends DataClass
    implements Insertable<PurchaseReturnAdjustment> {
  final String? warehouseId;
  final int id;
  final String returnNumber;
  final int supplierId;
  final int currencyId;
  final Decimal subtotalCents;
  final Decimal discountCents;
  final Decimal taxCents;
  final Decimal totalCents;

  /// draft, posted, voided
  final String status;

  /// cash, credit, cheque
  final String refundMethod;

  /// auto_adjustment, price_mismatch, no_invoice, quantity_overflow
  final String? returnMode;

  /// Human-readable reason the system chose this mode
  final String? modeReason;

  /// Groups linked + adjustment records created in the same unified return submission
  final String? batchId;

  /// Client-generated idempotency token. Unique when present so a duplicated
  /// submission (double-tap, network retry) can never create two ledgers.
  final String? idempotencyKey;

  /// Phase 2.4 — FX rate to base currency on post date (Decimal as TEXT).
  final String? fxRateToBase;
  final String? notes;
  final String approvalStatus;
  final bool approvalRequired;
  final String? approvalReason;
  final int? approvedBy;
  final DateTime? approvedAt;
  final String? overrideReason;
  final int? overrideBy;
  final int? postedBy;
  final DateTime? postedAt;
  final int? voidedBy;
  final DateTime? voidedAt;
  final String? voidReason;
  final int? reasonCodeId;
  final DateTime returnDate;
  final DateTime? dueDate;

  /// Phase 11.2 — pricing engine version snapshot. See `Sales`.
  final String? pricingEngineVersion;

  /// Phase 11.2 — tax-inclusive setting at post time.
  final bool? taxInclusiveAtPost;

  /// Phase 11.2 — rounding mode at post time.
  final String? roundingModeAtPost;
  final DateTime createdAt;
  final DateTime updatedAt;
