class BatchConsumption extends DataClass
    implements Insertable<BatchConsumption> {
  final int id;
  final int batchId;

  /// One of: 'sale' | 'sale_return_reverse' | 'purchase_return' |
  ///         'shrinkage' | 'revaluation' | 'purchase_adj_return' |
  ///         'sale_adj_return_reverse' | 'void_purchase' | 'void_sale_reverse'.
  final String consumptionType;

  /// 'out' = quantity removed from batch ; 'in' = quantity restored to batch.
  final String direction;
  final int quantity;

  /// Frozen unit cost at the time of consumption. For 'in' directions this is
  /// the cost the batch carried when the original 'out' was recorded so that
  /// reversals are perfectly symmetric.
  final Decimal unitCostCents;
  final int? saleItemId;
  final int? saleReturnItemId;
  final int? purchaseReturnItemId;
  final int? inventoryAdjustmentId;
  final int? purchaseReturnAdjustmentItemId;
  final int? saleReturnAdjustmentItemId;

  /// Allocation identity for FIFO warehouse dispatch and its exact recall.
  /// SQLite guards validate the relationship to avoid a table import cycle.
  final String? transferAllocationId;
  final String? notes;
  final DateTime createdAt;
  const BatchConsumption({
    required this.id,
    required this.batchId,
    required this.consumptionType,
    required this.direction,
    required this.quantity,
    required this.unitCostCents,
    this.saleItemId,
    this.saleReturnItemId,
    this.purchaseReturnItemId,
    this.inventoryAdjustmentId,
    this.purchaseReturnAdjustmentItemId,
    this.saleReturnAdjustmentItemId,
    this.transferAllocationId,
    this.notes,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['batch_id'] = Variable<int>(batchId);
    map['consumption_type'] = Variable<String>(consumptionType);
    map['direction'] = Variable<String>(direction);
    map['quantity'] = Variable<int>(quantity);
    {
      map['unit_cost_cents'] = Variable<int>(
        $BatchConsumptionsTable.$converterunitCostCents.toSql(unitCostCents),
      );
    }
    if (!nullToAbsent || saleItemId != null) {
      map['sale_item_id'] = Variable<int>(saleItemId);
    }
    if (!nullToAbsent || saleReturnItemId != null) {
      map['sale_return_item_id'] = Variable<int>(saleReturnItemId);
    }
    if (!nullToAbsent || purchaseReturnItemId != null) {
      map['purchase_return_item_id'] = Variable<int>(purchaseReturnItemId);
    }
    if (!nullToAbsent || inventoryAdjustmentId != null) {
      map['inventory_adjustment_id'] = Variable<int>(inventoryAdjustmentId);
    }
    if (!nullToAbsent || purchaseReturnAdjustmentItemId != null) {
